package org.retrobridge.gmail2012.provider;
import android.content.*;import android.database.*;import android.database.sqlite.*;import android.net.Uri;import android.util.Base64;import org.json.*;import java.io.*;import java.util.*;
/** Drains only operations created by original Gmail controls. Durable private requests survive reconnects. */
public final class PixelOutbox {
 static String uuid(android.content.SharedPreferences p,String key){String v=p.getString(key,"");if(v.isEmpty()){v=UUID.randomUUID().toString();if(!p.edit().putString(key,v).commit())throw new IllegalStateException("Cannot save action identity");}return v;}
 static String label(MailEngine e,long id)throws Exception {SQLiteDatabase db=(SQLiteDatabase)PixelMail.field(e,"mDb");Cursor c=db.query("labels",new String[]{"canonicalName"},"_id=?",new String[]{Long.toString(id)},null,null,null);try{if(!c.moveToFirst())return null;String name=c.getString(0);for(int i=0;i<PixelMail.BUILTINS.length;i++)if(PixelMail.BUILTINS[i].equals(name)){String api=PixelMail.API[i];return api.matches("INBOX|UNREAD|STARRED|TRASH|SPAM|IMPORTANT")?api:null;}if(name.equals("^^important")||name.equals("^im"))return "IMPORTANT";return name.startsWith("pixel:Label_")?name.substring(6):null;}finally{c.close();}}
 public static void kick(MailEngine e){try{flush(e);}catch(Exception ex){android.util.Log.w("PixelGmail",PixelMail.safeError(ex));}}
 public static synchronized void flush(MailEngine e)throws Exception {
  if(PixelMail.isFixture(e.getContext()))return;
  SQLiteDatabase db=(SQLiteDatabase)PixelMail.field(e,"mDb");android.content.SharedPreferences p=e.getContext().getSharedPreferences("pixel-outbox-"+e.getAccountName(),0);
  Cursor rows=db.query("operations",new String[]{"_id","action","message_messageId","value1","value2"},null,null,null,null,"_id ASC","100");List<Object[]> ops=new ArrayList<Object[]>();try{while(rows.moveToNext())ops.add(new Object[]{rows.getLong(0),rows.getString(1),rows.getLong(2),rows.getLong(3),rows.getLong(4)});}finally{rows.close();}
  for(Object[] item:ops){long opId=(Long)item[0],mid=(Long)item[2],lid=(Long)item[3],thread=(Long)item[4];String action=(String)item[1],identity=uuid(p,"op:"+opId);JSONObject request;
   String saved=p.getString("request:"+opId,"");
   if(!saved.isEmpty())request=new JSONObject(saved);
   else if(action.endsWith("LabelAdded")||action.endsWith("LabelRemoved")){String lab=label(e,lid);if(lab==null){db.delete("operations","_id=?",new String[]{Long.toString(opId)});continue;}boolean conversation=action.startsWith("conversation");request=PixelMail.request(e,"modify").put("target",conversation?"threads":"messages").put("id",Long.toHexString(conversation?thread:mid)).put("label",lab).put("add",action.endsWith("Added"));}
   else if(action.equals("messageSent")||action.equals("messageSaved")){
    MailSync.Message m=e.getMessage(mid,true);if(m==null){db.delete("operations","_id=?",new String[]{Long.toString(opId)});continue;}
    String draftKey=uuid(p,"draft:"+mid);boolean draft=action.equals("messageSaved");
    request=PixelMail.request(e,draft?"draft":"send").put("requestId",identity).put("draftKey",draftKey);byte[] payload=mime(e,m,identity);if(payload.length<200000)request.put("raw",Base64.encodeToString(payload,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING));else{String hash=sha(payload);for(int offset=0;offset<payload.length;){int count=Math.min(196608,payload.length-offset);byte[] part=java.util.Arrays.copyOfRange(payload,offset,offset+count);JSONObject ack=PixelMail.call(PixelMail.request(e,"upload").put("sha256",hash).put("total",payload.length).put("offset",offset).put("data",Base64.encodeToString(part,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING)));if(ack.getInt("next")!=offset+count)throw new IOException("Upload offset mismatch");offset+=count;}request.put("upload",hash);}
    if(m.refMessageId>0){MailSync.Message ref=e.getMessage(m.refMessageId,false);if(ref!=null&&ref.conversationId>0&&!m.forward)request.put("thread",Long.toHexString(ref.conversationId));}
   }else if(action.equals("messageExpunged")){String draftKey=p.getString("draft:"+mid,"");if(draftKey.isEmpty())throw new IOException("Permanent deletion is unavailable on S2");request=PixelMail.request(e,"discardDraft").put("requestId",identity).put("draftKey",draftKey);}
   else throw new IOException("Unsupported queued mail action");
   if(!p.edit().putString("request:"+opId,request.toString()).commit())throw new IOException("Cannot save outgoing message");
   JSONObject result=PixelMail.call(request);
   if(action.equals("messageSent")||action.equals("messageSaved")){JSONObject msg=result.has("message")?result.getJSONObject("message"):result;long newId=PixelMail.id(msg.getString("id")),newThread=PixelMail.id(msg.getString("threadId"));String draftKey=request.getString("draftKey");p.edit().putString("draft:"+newId,draftKey).commit();e.mMailStore.updateSentOrSavedMessage(mid,newId,newThread);}
   db.delete("operations","_id=?",new String[]{Long.toString(opId)});p.edit().remove("request:"+opId).remove("op:"+opId).commit();
  }
  if(!ops.isEmpty())PixelMail.changed(e);
 }
 static String sha(byte[] data)throws Exception{StringBuilder out=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(data))out.append(String.format(java.util.Locale.US,"%02x",b&255));return out.toString();}
 static String header(String s)throws IOException{if(s==null)return "";if(s.indexOf('\r')>=0||s.indexOf('\n')>=0||s.indexOf('\0')>=0||s.length()>10000)throw new IOException("Invalid message header");return s;}
 static String recipients(List<String> addresses)throws IOException {StringBuilder out=new StringBuilder();if(addresses!=null)for(String a:addresses){if(out.length()>0)out.append(", ");out.append(header(a));}return out.toString();}
 static void line(ByteArrayOutputStream out,String text)throws Exception {out.write((text+"\r\n").getBytes("UTF-8"));}
 static byte[] mime(MailEngine e,MailSync.Message m,String key)throws Exception {
  String boundary="galaxy-"+key;ByteArrayOutputStream out=new ByteArrayOutputStream();line(out,"From: "+header(e.getAccountName()));line(out,"Message-ID: <"+key+"@galaxy-s2.local>");if(m.refMessageId>0&&!m.forward){String message=e.getContext().getSharedPreferences("pixel-rfc",0).getString(Long.toHexString(m.refMessageId),"");if(message.matches("<[^<>\\r\\n]{1,500}>")){line(out,"In-Reply-To: "+message);String refs=e.getContext().getSharedPreferences("pixel-rfc",0).getString(Long.toHexString(m.refMessageId)+":refs","");if(refs.length()>6000)refs="";line(out,"References: "+header(refs)+" "+message);}}line(out,"To: "+recipients(m.toAddresses));line(out,"Cc: "+recipients(m.ccAddresses));line(out,"Bcc: "+recipients(m.bccAddresses));line(out,"Subject: =?UTF-8?B?"+Base64.encodeToString((m.subject==null?"":m.subject).getBytes("UTF-8"),Base64.NO_WRAP)+"?=");line(out,"MIME-Version: 1.0");line(out,"Content-Type: multipart/mixed; boundary=\""+boundary+"\"");line(out,"");line(out,"--"+boundary);line(out,"Content-Type: text/html; charset=UTF-8");line(out,"Content-Transfer-Encoding: base64");line(out,"");String body=m.body==null?"":m.body;
  if(m.includeQuotedText&&m.refMessageId>0){MailSync.Message ref=e.getMessage(m.refMessageId,true);if(ref!=null&&ref.body!=null)body+="<br><blockquote>"+ref.body+"</blockquote>";}
  line(out,Base64.encodeToString(body.getBytes("UTF-8"),Base64.CRLF));
  if(m.attachments!=null)for(Gmail.Attachment a:m.attachments){InputStream in=null;try{if(a.cachedContent!=null&&new File(a.cachedContent).isFile())in=new FileInputStream(a.cachedContent);else in=e.getContext().getContentResolver().openInputStream(Uri.parse(a.originExtras));if(in==null)throw new IOException("Attachment unavailable");ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(bytes.size()+n>5000000)throw new IOException("Attachment exceeds current device transfer limit");bytes.write(buf,0,n);}line(out,"--"+boundary);String type=a.contentType!=null&&a.contentType.matches("[A-Za-z0-9.+-]+/[A-Za-z0-9.+-]+")?a.contentType:"application/octet-stream";String name=header(a.name).replace("\\","_").replace("\"","_");line(out,"Content-Type: "+type+"; name=\""+name+"\"");line(out,"Content-Disposition: attachment; filename=\""+name+"\"");line(out,"Content-Transfer-Encoding: base64");line(out,"");line(out,Base64.encodeToString(bytes.toByteArray(),Base64.CRLF));}finally{if(in!=null)in.close();}}
  line(out,"--"+boundary+"--");if(out.size()>8000000)throw new IOException("Message exceeds current device transfer limit");return out.toByteArray();
 }
}
